[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>300 Years of Sclerosponge Thermometry - Academic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --ocean-deep:   #0a1628;
    --ocean-mid:    #0d2744;
    --ocean-blue:   #1a4a7a;
    --ocean-teal:   #1e6b8a;
    --mid-blue:     #2d88b0;
    --cool-grey:    #4a6fa5;
    --neutral-bg:   #f0f4f8;
    --warm-amber:   #d97706;
    --warm-orange:  #ea580c;
    --warm-red:     #dc2626;
    --deep-red:     #991b1b;
    --gold:         #f59e0b;
    --white:        #ffffff;
    --light-grey:   #e2e8f0;
    --text-primary: #0f172a;
    --text-secondary: #334155;
    --text-muted:   #64748b;
    --paris-line:   #dc2626;
    --accent-green: #059669;
  }

  body {
    width: 2384px;
    height: 3370px;
    background: var(--ocean-deep);
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    color: var(--white);
    overflow: hidden;
    position: relative;
  }

  /* ── Background ocean texture ── */
  .bg-texture {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse 120% 60% at 50% 0%, rgba(29,78,216,0.18) 0%, transparent 60%),
      radial-gradient(ellipse 80% 40% at 0% 100%, rgba(220,38,38,0.10) 0%, transparent 50%),
      radial-gradient(ellipse 60% 30% at 100% 80%, rgba(217,119,6,0.08) 0%, transparent 40%),
      linear-gradient(180deg, #0a1628 0%, #0d2744 40%, #0f1f38 70%, #130d1a 100%);
    pointer-events: none;
  }

  .bg-grid {
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
    background-size: 120px 120px;
    pointer-events: none;
  }

  /* ── Layout ── */
  .poster {
    position: relative;
    width: 2384px;
    height: 3370px;
    display: flex;
    flex-direction: column;
    padding: 80px 80px 60px;
    gap: 0;
  }

  /* ── Header ── */
  .header {
    background: linear-gradient(135deg, rgba(13,39,68,0.95) 0%, rgba(26,74,122,0.90) 100%);
    border: 1px solid rgba(45,136,176,0.4);
    border-radius: 20px;
    padding: 60px 72px 52px;
    margin-bottom: 40px;
    position: relative;
    overflow: hidden;
  }
  .header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 5px;
    background: linear-gradient(90deg, #1e6b8a, #2d88b0, #f59e0b, #ea580c, #dc2626);
  }

  .header-venue {
    font-size: 28px;
    font-weight: 500;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #93c5fd;
    margin-bottom: 20px;
  }

  .header-title {
    font-size: 78px;
    font-weight: 800;
    line-height: 1.1;
    color: var(--white);
    margin-bottom: 28px;
    letter-spacing: -0.02em;
  }
  .header-title .highlight-warm {
    color: #fbbf24;
  }

  .header-subtitle {
    font-size: 34px;
    font-weight: 400;
    color: rgba(255,255,255,0.78);
    line-height: 1.45;
    max-width: 1800px;
    font-style: italic;
  }

  .header-source {
    margin-top: 22px;
    font-size: 24px;
    color: #60a5fa;
    font-weight: 500;
  }

  /* ── Stats Strip ── */
  .stats-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 28px;
    margin-bottom: 40px;
  }

  .stat-card {
    background: linear-gradient(135deg, rgba(13,39,68,0.95) 0%, rgba(22,60,100,0.90) 100%);
    border-radius: 16px;
    padding: 36px 32px;
    border: 1px solid rgba(45,136,176,0.35);
    position: relative;
    overflow: hidden;
  }
  .stat-card::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 4px;
    border-radius: 0 0 16px 16px;
  }
  .stat-card.blue::after   { background: linear-gradient(90deg, #1e6b8a, #2d88b0); }
  .stat-card.amber::after  { background: linear-gradient(90deg, #d97706, #f59e0b); }
  .stat-card.red::after    { background: linear-gradient(90deg, #dc2626, #991b1b); }
  .stat-card.green::after  { background: linear-gradient(90deg, #059669, #10b981); }

  .stat-value {
    font-size: 68px;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 8px;
    letter-spacing: -0.03em;
  }
  .stat-card.blue  .stat-value { color: #60a5fa; }
  .stat-card.amber .stat-value { color: #fbbf24; }
  .stat-card.red   .stat-value { color: #f87171; }
  .stat-card.green .stat-value { color: #34d399; }

  .stat-label {
    font-size: 22px;
    color: rgba(255,255,255,0.70);
    line-height: 1.35;
    font-weight: 400;
  }

  /* ── Main grid ── */
  .main-grid {
    display: grid;
    grid-template-columns: 1fr 640px;
    gap: 32px;
    flex: 1;
    min-height: 0;
  }

  .left-col {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  .right-col {
    display: flex;
    flex-direction: column;
    gap: 32px;
  }

  /* ── Panel base ── */
  .panel {
    background: linear-gradient(135deg, rgba(13,39,68,0.95) 0%, rgba(22,60,100,0.85) 100%);
    border: 1px solid rgba(45,136,176,0.30);
    border-radius: 18px;
    padding: 44px 48px;
    position: relative;
    overflow: hidden;
  }

  .panel-title {
    font-size: 30px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    color: #93c5fd;
    margin-bottom: 28px;
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .panel-title::before {
    content: '';
    display: block;
    width: 6px;
    height: 30px;
    background: linear-gradient(180deg, #2d88b0, #60a5fa);
    border-radius: 3px;
    flex-shrink: 0;
  }

  /* ── Temperature Chart ── */
  .chart-panel {
    flex: 1;
  }

  .chart-title {
    font-size: 38px;
    font-weight: 800;
    color: var(--white);
    margin-bottom: 8px;
  }

  .chart-subtitle {
    font-size: 22px;
    color: rgba(255,255,255,0.60);
    margin-bottom: 40px;
  }

  .chart-container {
    position: relative;
    width: 100%;
  }

  svg.temp-chart {
    width: 100%;
    height: auto;
    overflow: visible;
  }

  /* ── Baseline Comparison ── */
  .baseline-compare {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .compare-side {
    border-radius: 14px;
    padding: 32px 28px;
    position: relative;
    overflow: hidden;
  }
  .compare-side.ipcc {
    background: linear-gradient(135deg, rgba(29,78,216,0.25) 0%, rgba(30,107,138,0.20) 100%);
    border: 1px solid rgba(45,136,176,0.50);
  }
  .compare-side.true-pi {
    background: linear-gradient(135deg, rgba(153,27,27,0.30) 0%, rgba(217,119,6,0.20) 100%);
    border: 1px solid rgba(220,38,38,0.50);
  }

  .compare-tag {
    font-size: 18px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    margin-bottom: 10px;
  }
  .compare-side.ipcc .compare-tag    { color: #60a5fa; }
  .compare-side.true-pi .compare-tag { color: #fca5a5; }

  .compare-temp {
    font-size: 88px;
    font-weight: 900;
    line-height: 1;
    letter-spacing: -0.04em;
    margin-bottom: 6px;
  }
  .compare-side.ipcc .compare-temp    { color: #93c5fd; }
  .compare-side.true-pi .compare-temp { color: #f87171; }

  .compare-baseline {
    font-size: 20px;
    color: rgba(255,255,255,0.60);
    margin-bottom: 10px;
  }

  .compare-note {
    font-size: 19px;
    color: rgba(255,255,255,0.75);
    line-height: 1.4;
  }

  .hidden-warming-callout {
    grid-column: 1 / -1;
    background: linear-gradient(135deg, rgba(217,119,6,0.30) 0%, rgba(234,88,12,0.25) 100%);
    border: 2px solid rgba(251,191,36,0.60);
    border-radius: 14px;
    padding: 24px 28px;
    display: flex;
    align-items: center;
    gap: 20px;
  }

  .hidden-warming-arrow {
    font-size: 56px;
    font-weight: 900;
    color: #fbbf24;
    flex-shrink: 0;
    line-height: 1;
  }

  .hidden-warming-text {
    font-size: 24px;
    color: rgba(255,255,255,0.90);
    line-height: 1.4;
  }
  .hidden-warming-text strong {
    color: #fbbf24;
    font-size: 28px;
  }

  /* ── Why Sclerosponges ── */
  .feature-list {
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  .feature-item {
    display: flex;
    gap: 18px;
    align-items: flex-start;
  }

  .feature-dot {
    width: 12px;
    height: 12px;
    background: #2d88b0;
    border-radius: 50%;
    margin-top: 9px;
    flex-shrink: 0;
    box-shadow: 0 0 8px rgba(45,136,176,0.7);
  }

  .feature-text {
    font-size: 24px;
    line-height: 1.5;
    color: rgba(255,255,255,0.85);
  }
  .feature-text strong {
    color: #60a5fa;
    font-weight: 600;
  }

  /* ── Timeline list ── */
  .timeline-list {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
  }
  .timeline-list::before {
    content: '';
    position: absolute;
    left: 18px;
    top: 16px;
    bottom: 16px;
    width: 2px;
    background: linear-gradient(180deg, #1e6b8a, #2d88b0, #d97706, #dc2626);
  }

  .timeline-item {
    display: flex;
    gap: 24px;
    padding: 14px 0 14px 52px;
    position: relative;
  }
  .timeline-dot {
    position: absolute;
    left: 8px;
    top: 22px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    border: 3px solid var(--white);
    flex-shrink: 0;
  }
  .timeline-item:nth-child(1) .timeline-dot { background: #1e6b8a; }
  .timeline-item:nth-child(2) .timeline-dot { background: #2d88b0; }
  .timeline-item:nth-child(3) .timeline-dot { background: #4a6fa5; }
  .timeline-item:nth-child(4) .timeline-dot { background: #d97706; }
  .timeline-item:nth-child(5) .timeline-dot { background: #ea580c; }
  .timeline-item:nth-child(6) .timeline-dot { background: #dc2626; }

  .timeline-period {
    font-size: 20px;
    font-weight: 700;
    color: #93c5fd;
    min-width: 130px;
    flex-shrink: 0;
    line-height: 1.5;
  }
  .timeline-obs {
    font-size: 21px;
    color: rgba(255,255,255,0.80);
    line-height: 1.5;
  }

  /* ── Policy implications ── */
  .policy-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .policy-item {
    background: rgba(255,255,255,0.04);
    border-left: 4px solid #2d88b0;
    padding: 20px 24px;
    border-radius: 0 10px 10px 0;
    font-size: 22px;
    color: rgba(255,255,255,0.82);
    line-height: 1.45;
  }
  .policy-item strong { color: #fbbf24; }
  .policy-item.urgent { border-left-color: #dc2626; }
  .policy-item.urgent strong { color: #f87171; }

  /* ── Methods ── */
  .methods-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .method-item {
    background: rgba(255,255,255,0.04);
    border-radius: 10px;
    padding: 20px 22px;
  }
  .method-label {
    font-size: 18px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #7dd3fc;
    margin-bottom: 6px;
  }
  .method-value {
    font-size: 21px;
    color: rgba(255,255,255,0.80);
    line-height: 1.4;
  }

  /* ── Footer ── */
  .footer {
    margin-top: 28px;
    padding: 28px 40px;
    background: linear-gradient(135deg, rgba(13,39,68,0.90) 0%, rgba(22,60,100,0.80) 100%);
    border: 1px solid rgba(45,136,176,0.25);
    border-radius: 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 20px;
    color: rgba(255,255,255,0.50);
  }
  .footer strong { color: rgba(255,255,255,0.70); }
</style>
</head>
<body>
<div class="bg-texture"></div>
<div class="bg-grid"></div>

<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-venue">AGU / Nature Climate Change Symposium · 2024</div>
    <div class="header-title">
      300 Years of Sclerosponge Thermometry Shows<br>
      Global Warming Has <span class="highlight-warm">Already Exceeded 1.5 °C</span>
    </div>
    <div class="header-subtitle">
      Sclerosponge-derived ocean temperature records spanning three centuries reveal that anthropogenic warming
      has surpassed the critical Paris Agreement threshold — when measured against a <em>true</em> pre-industrial baseline.
    </div>
    <div class="header-source">Published in <em>Nature Climate Change</em>, 2024 &nbsp;·&nbsp; Sr/Ca proxy thermometry, Caribbean reef sites</div>
  </div>

  <!-- STATS STRIP -->
  <div class="stats-strip">
    <div class="stat-card blue">
      <div class="stat-value">~300</div>
      <div class="stat-label">Years of continuous<br>temperature record (back to ~1700 CE)</div>
    </div>
    <div class="stat-card amber">
      <div class="stat-value">+0.5°C</div>
      <div class="stat-label">Hidden warming already present<br>by 1850–1900 (IPCC start date)</div>
    </div>
    <div class="stat-card red">
      <div class="stat-value">&gt;1.5°C</div>
      <div class="stat-label">Total warming from true<br>pre-industrial baseline (by 2020s)</div>
    </div>
    <div class="stat-card green">
      <div class="stat-value">r²&gt;0.9</div>
      <div class="stat-label">Proxy calibration accuracy<br>vs. instrumental 1960–present</div>
    </div>
  </div>

  <!-- MAIN GRID -->
  <div class="main-grid">

