            </defs>

            <!-- Chart area background -->
            <rect x="90" y="30" width="1420" height="560" fill="rgba(10,22,40,0.50)" rx="8"/>

            <!-- Grid lines Y -->
            <!-- y=0 -> y_px=474, y=0.5->y_px=334, y=1.0->y_px=194, y=1.5->y_px=54, y=-0.5->y_px=614 -->
            <!-- Scale: 0°C at y=474, 1°C = 280px, chart top=30, bottom=590 -->
            <!-- y_px = 474 - (val * 280) -->

            <line x1="90" y1="614" x2="1510" y2="614" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>
