              C1470,28 1481,18 1492,8
              L1492,590 Z"
              fill="url(#curveGrad)" opacity="0.70"/>

            <!-- Sclerosponge curve line -->
            <path d="M90,460 C110,463 130,469 134,466 C156,460 166,458 178,457
              C200,461 212,464 222,463 C244,458 255,455 266,454
              C288,459 300,461 309,460 C331,455 342,453 353,452
              C375,456 385,458 397,457 C419,451 430,450 441,449
              C463,451 474,452 485,452
              C507,440 518,430 529,424 C551,420 562,428 572,432
              C594,422 605,415 616,412 C638,402 649,398 660,396
              C682,385 693,380 704,376 C726,360 737,347 748,334
              C770,330 781,329 791,328 C813,323 824,321 835,320
              C857,315 867,313 879,311 C901,320 912,325 923,328
              C945,316 956,311 966,306
              C988,309 999,311 1010,312 C1032,305 1043,302 1054,300
              C1076,291 1087,287 1098,284 C1120,277 1131,274 1142,272
              C1164,269 1175,268 1185,267
              C1207,262 1218,259 1229,256 C1251,246 1262,241 1273,237
              C1295,218 1306,209 1317,200 C1339,179 1350,169 1361,160
              C1383,132 1394,118 1404,105 C1426,77 1437,63 1448,49
