            <!-- Instrumental record (starts ~1850, slightly lower values) -->
            <!-- Instrumental anomaly vs TRUE pre-industrial baseline: -->
            <!-- 1850: 0.50, 1900: 0.60, 1950: 0.74, 1960: 0.78, 1970: 0.85, 1980: 0.98, 1990: 1.12, 2000: 1.32, 2010: 1.50, 2020: 1.68 -->
