            <!-- Threshold crossing point indicator -->
            <!-- 1.5°C crossed ~2010: x=1448, y=49+5=54 -->
            <circle cx="1448" cy="49" r="14" fill="#dc2626" stroke="#ffffff" stroke-width="3" filter="url(#glow)"/>
            <text x="1448" y="28" fill="#fca5a5" font-size="21" text-anchor="middle" font-family="Inter" font-weight="700">1.5°C CROSSED</text>
            <text x="1448" y="8" fill="#fca5a5" font-size="19" text-anchor="middle" font-family="Inter">~2010</text>

            <!-- Hidden warming arrow annotation -->
            <!-- At 1850 (x=748): sclero at 334 (0.5°C), IPCC baseline at 474 (0°C) -->
            <line x1="810" y1="340" x2="810" y2="476" stroke="#fbbf24" stroke-width="2.5" marker-end="url(#arrowDown)" marker-start="url(#arrowUp)" stroke-dasharray="4,3"/>
