            <rect x="820" y="383" width="175" height="48" fill="rgba(20,20,20,0.75)" rx="6"/>
            <text x="907" y="406" fill="#fbbf24" font-size="20" font-weight="700" text-anchor="middle" font-family="Inter">Hidden +0.5°C</text>
            <text x="907" y="424" fill="rgba(255,255,255,0.70)" font-size="17" text-anchor="middle" font-family="Inter">already by 1850</text>

            <!-- Legend -->
