            <text x="966"  y="606" fill="rgba(255,255,255,0.55)" font-size="20" text-anchor="middle" font-family="Inter">1900</text>
            <text x="1185" y="606" fill="rgba(255,255,255,0.55)" font-size="20" text-anchor="middle" font-family="Inter">1950</text>
